        }

        public virtual void Write(GbxWriter w, CPlugAnimFile n, int v = 0)
        {
            w.WriteWritable<CPlugAnimSkelBaked.TimingFixedPeriod>(this.timing, version: n. TimingFixedPeriodVersion);
            w.Write(this.jointGroupIndex);
            w.WriteArray<TransQuat>(this.localJointsData);

            if (v == 1)
            {
                w.Write(this.u01);
            }

            if (v >= 3)
            {
                w.WriteWritable<CPlugAnimClip.ClipFlags>(this.flags, version: n. ClipFlagsVersion);
            }

            if (v >= 4)
            {
                w.WriteArrayWritable<RootMotionFrame>(this.rootMotionFrames, version: v);
            }

            if (v >= 5)
            {
                w.WriteArrayId(this.floatChannelIds);
                w.WriteArray<float>(this.floatChannelData);
            }
        }
    }

